package conversationruntime

import (
	"errors"
	"fmt"
)

// ConfirmNative records product-visible text generated by this exact native
// session (e.g. its final assistant reply). The adapter must have observed the
// reply on that session; this is NOT an inferred acknowledgement or a search
// for matching text. No credentials, reasoning or tool state belong here.
// Product append and native confirmation are separate in-memory calls in B1;
// durable atomicity is deliberately a later integration gate.
func (l *Ledger) ConfirmNative(store *BindingStore, bindingID, nativeID, entryID string, rev int, digest string) error {
	if l == nil || store == nil {
		return errors.New("conversationruntime: nil ledger or store")
	}
	store.mu.Lock()
	defer store.mu.Unlock()
	l.mu.Lock()
	defer l.mu.Unlock()
	b, ok := store.b[bindingID]
	if !ok {
		return ErrNoSuchBinding
	}
	if nativeID == "" || nativeID != b.NativeSessionID || !b.Status.Safe() {
		return ErrStaleBinding
	}
	e, ok := l.latest[entryID]
	if !ok || e.Tombstone || e.Role != "assistant" || len(e.Attachments) > 0 || e.Revision != rev || TextDigest(e.Text) != digest {
		return fmt.Errorf("%w: native reply does not match product revision", ErrStalePlan)
	}
	next := b.clone()
	next.Coverage.Delivered[entryID] = RevisionDigest{Rev: rev, Digest: digest}
	delete(next.Coverage.Partial, entryID)
	store.b[bindingID] = next
	return nil
}
